cat > c.mjs <<'E'
import { chromium } from 'playwright';
const b=await chromium.launch();const p=await b.newPage();
await p.goto('http://127.0.0.1:65166');
await p.fill('input[type=email],input[name=email]','ops@lab.test');
await p.fill('input[type=password]','lab-ops-pass');
await p.keyboard.press('Enter');
await p.waitForTimeout(1500);
await p.goto('http://127.0.0.1:65166/refunds');
for(let pg=1;pg<=3;pg++){
 const rows=await p.$$eval('tr[data-id]',r=>r.map(x=>[x.dataset.id,...[...x.cells].map(c=>c.innerText)]));
 for(const [id,,cust,reason,amt,st] of rows){
  if(st.trim()!='Pending')continue;
  const n=+amt.replace(/[^\d]/g,'');
  let a=null;
  if(/Blocked/.test(cust))a='.rj';else if(reason=='Damaged item'&&n<=500)a='.ap';
  console.log(pg,id,cust,reason,amt,a);
  if(a){await p.click(`tr[data-id="${id}"] ${a}`);await p.waitForTimeout(600);
   console.log(await p.innerText(`tr[data-id="${id}"]`).catch(()=>'gone'));}
 }
 const nx=p.getByText('Next');
 if(pg<3){await nx.click();await p.waitForTimeout(800);}
}
await b.close();
E
